  let udpVerbosity = 2; // Low verbosity score for UDP as it involves minimal interaction

  let ipv6Rating = ipv6Helpfulness * 94 + ipv6Verbosity * 34;
  let httpRating = httpHelpfulness * 94 + httpVerbosity * 34;
  let udpRating = udpHelpfulness * 94 + udpVerbosity * 34;

  if (inputData.protocol && inputData.protocol === 'IPv6') {
    return 'Option A'; // If the input explicitly states IPv6, return IPv6
  }

  if (ipv6Rating > httpRating && ipv6Rating > udpRating) {
    return 'Option A'; // If IPv6 has the highest rating, return IPv6
  } else if (httpRating > ipv6Rating && httpRating > udpRating) {
    return 'Option B'; // If HTTP has the highest rating, return HTTP
  } else {
    return 'Option C'; // Otherwise, default to UDP
  }
}

