 Here's an example of a simple decorator for Nest.js middleware that checks the `NODE_ENV` environment variable and either calls the next handler or returns `false` based on its value:

```typescript
import { createDecorator, ExecutionContext } from '@nestjs/common';

export const EnvCheckMiddleware = createDecorator(
  (allowedEnv: string[], options?: object) => ({
    name: 'env-check-middleware',
    multiApply: true,
    global: false,
    useFactory: (logger: any) => ({
      use: (ctx: ExecutionContext, next: Function) => {
        const req = ctx.switchToHttp().getRequest();
        const nodeEnv = process.env.NODE_ENV;

        if (allowedEnv.includes(nodeEnv)) {
          return next();
        } else {
          logger.log('NODE_ENV is not allowed. Returning false.');
          return false;
        }
      },
    }),
  }),
);

// Usage example:
@Controller()
@UseGlobalPipes(ValidationPipe())
@UseMiddleware(EnvCheckMiddleware({ allowedEnv: ['production'] }))
export class AppController {
  // ...
}
```

This decorator accepts an array of allowed environments as its argument and creates a factory function to define the middleware logic. The middleware uses the provided `logger` to log messages when the condition is met. If the `NODE_ENV` is not included in the allowed list, it returns `false`.

You can apply this decorator to a controller or route level using the `@UseMiddleware()` decorator. In this example, the middleware is set up to only allow requests with a `NODE_ENV` of "production". Adjust the `allowedEnv` array accordingly to meet your needs.

