 Certainly! Here are four methods using the MediaDevices API to handle opening, closing, and checking the status of both the camera and microphone in JavaScript:

1. Opening and Closing Camera and Microphone

```javascript
async function startMediaStream(deviceType) {
  let stream;
  try {
    const constraints = deviceType === 'camera' ? { video: true } : { audio: true };
    stream = await navigator.mediaDevices.getUserMedia(constraints);
  } catch (error) {
    console.error('Error accessing media devices.', error);
  }

  return stream;
}

async function stopMediaStream(stream) {
  try {
    await stream.getTracks().forEach((track) => track.stop());
  } catch (error) {
    console.error('Error stopping media stream.', error);
  }
}
```

2. Checking the Status of Camera and Microphone

```javascript
function checkMediaDeviceAvailability(deviceType) {
  navigator.mediaDevices.enumerateDevices()
    .then((devices) => {
      const device = devices.find((device) => device.kind === deviceType);
      if (device) {
        console.log(`${deviceType} available: ${device.label}`);
      } else {
        console.error(`No ${deviceType} found.`);
      }
    })
    .catch((error) => console.error('Error retrieving media devices.', error));
}
```

3. Opening and Closing Camera and Microphone with Promises

```javascript
async function startMediaStreamPromise(deviceType) {
  try {
    const constraints = deviceType === 'camera' ? { video: true } : { audio: true };
    const stream = await new Promise((resolve, reject) => {
      navigator.mediaDevices.getUserMedia(constraints)
        .then((stream) => resolve(stream))
        .catch((error) => reject(error));
    });
    return stream;
  } catch (error) {
    console.error('Error accessing media devices.', error);
  }
}

