  domain: 'yourdomain',
  clientID: 'yourclientid',
  redirectUri: window.location.origin
});

// Get user session
auth0.parseHash((err, result) => {
  if (err) return console.error(err);
  if (!result || !result.accessToken || !result.idToken) return;

  // User is authenticated and has a valid session.
  const userSession = result.idTokenClaims;
  console.log("User session:", userSession);
});
```

Remember to replace `'yourdomain'`, `'yourclientid'`, and other placeholders with your actual values from your SDK configuration. Always refer to the official documentation of the specific SDK you're using for accurate instructions.

 Here's an example implementation of the `RedisClient` class as requested:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  async isAlive() {
    return new Promise((resolve, reject) => {
      this.client.ping((err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply === 'PONG');
        }
      });
    });
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          reject(err);
        } else {
          resolve(value);
        }
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

